/// CodeMie authentication helpers: browser-based SSO (`/v1/auth/login/<port>`
/// redirects to a localhost callback with a base64 token carrying session
/// cookies) and JWT Bearer authorization. The CodeMie API accepts auth either
/// via the FULL cookie string (sent as a `Cookie:` header) from SSO, or via
/// an `Authorization: Bearer <jwt>` header for headless/CI use. The chat
/// traffic rides the standard openai-completions adapter: SSO uses a `cookie:`
/// model header that suppresses the default `authorization` header, while JWT
/// uses the adapter's regular Bearer auth path.
///
/// Pure Dart (no `dart:io`); the localhost callback server lives in
/// `lib/src/cli/codemie_sso_server.dart` (exported from `lib/io.dart`).
library;

import 'dart:convert';

import 'package:http/http.dart' as http;

import '../exceptions.dart';

/// The hosted CodeMie default (an on-prem org URL can always be typed).
const defaultCodeMieBaseUrl = 'https://codemie.lab.epam.com';

/// The `x-codemie-project` header name — the CodeMie backend attributes
/// every model request (billing, budget limits) to the project this header
/// names. A MISSING (or non-Latin-1) header falls back to the user's
/// DEFAULT project (codemie-code `header-injection.plugin.ts`, issue
/// #1941): requests without it bill the wrong project even though the UI
/// shows another one selected.
const codeMieProjectHeader = 'x-codemie-project';

/// The `x-codemie-client` header name — the CodeMie gateway picks the
/// BUDGET a request bills by this header (issue #2426): a request WITHOUT
/// it lands in the user's PERSONAL budget and dies with
/// `429 ExceededBudget` once personal spend is exhausted, even though the
/// client's org/app budget has headroom. A server quirk, not rate
/// limiting — the structured 429 decode and the queue cooldown keep
/// working unchanged.
const codeMieClientHeader = 'x-codemie-client';

/// The client identity sent as [codeMieClientHeader]: the value a CodeMie
/// org registers its client/app budget against (issue #2426). ASCII by
/// contract (`package:http` rejects non-Latin-1 header values).
const codeMieClient = 'flutter-agent-harness';

/// The always-on CodeMie request headers (issue #2426): EVERY request to a
/// CodeMie endpoint starts from this map — chat rides it through the
/// openai-completions defaults slot (URL-gated by [isCodeMieBaseUrl]),
/// the fetch family spreads it into its per-call header maps. The merge
/// order (defaults → `Model.headers` → options) keeps an explicit user
/// entry of the same name winning; the canonical name is lowercase (the
/// merge is case-sensitive by map key — E5).
const codeMieRequestHeaders = <String, String>{
  codeMieClientHeader: codeMieClient,
};

/// Normalizes an organization URL to the API base:
/// `https://host` → `https://host/code-assistant-api` (idempotent).
String codeMieApiBase(String rawUrl) {
  var base = rawUrl.trim().replaceAll(RegExp(r'/+$'), '');
  if (!RegExp(
    r'/code-assistant-api(/|$)',
    caseSensitive: false,
  ).hasMatch(base)) {
    base = '$base/code-assistant-api';
  }
  return base;
}

/// The SSO login URL embedding the local callback [port] — the organization
/// redirects to `http://localhost:<port>/?token=...` after the browser login.
String buildCodeMieSsoUrl(String codeMieUrl, int port) =>
    '${codeMieApiBase(codeMieUrl)}/v1/auth/login/$port';

/// True when [baseUrl] points at a CodeMie API endpoint
/// (`<org>/code-assistant-api[/v1]`).
bool isCodeMieBaseUrl(String baseUrl) =>
    RegExp(r'/code-assistant-api(/|$)', caseSensitive: false).hasMatch(baseUrl);

